// Input items are unsent rows
let allRows = [];
try {
  allRows = $('Get row(s) in sheet').all().map(i => i.json);
} catch (e) {
  allRows = $input.all().map(i => i.json);
}

for (const item of $input.all()) {
  const studentName = (item.json['اسم الطالب'] || '').trim();
  const rawScore = item.json['الدرجة'] || '';

  // Helper to parse score percentage
  let currentPct = 50;
  const match = String(rawScore).match(/^(\d+)\s*(?:\/|من)\s*(\d+)/);
  if (match) {
    const s = parseInt(match[1], 10);
    const t = parseInt(match[2], 10) || 5;
    currentPct = Math.round((s / t) * 100);
  } else {
    const n = parseInt(rawScore, 10);
    if (!isNaN(n)) currentPct = n > 5 ? n * 10 : n * 20;
  }

  // Find other previous tests for this student
  const studentHistory = allRows.filter(r => 
    (r['اسم الطالب'] || '').trim() === studentName && 
    r.row_number !== item.json.row_number &&
    r['الدرجة']
  );

  let previousPct = 75; // baseline expectation
  let hasHistory = false;
  if (studentHistory.length > 0) {
    let sum = 0;
    studentHistory.forEach(r => {
      const rm = String(r['الدرجة']).match(/^(\d+)\s*(?:\/|من)\s*(\d+)/);
      if (rm) sum += Math.round((parseInt(rm[1], 10) / (parseInt(rm[2], 10) || 5)) * 100);
      else sum += 75;
    });
    previousPct = Math.round(sum / studentHistory.length);
    hasHistory = true;
  }

  const dropPct = previousPct - currentPct;
  // Milestone Spec: "Gemini analyzes grade drop trends (>15%)"
  const isEarlyWarning = (dropPct >= 15) || (currentPct < 50);

  item.json.current_pct = currentPct;
  item.json.previous_pct = previousPct;
  item.json.drop_pct = Math.max(0, dropPct);
  item.json.is_early_warning = isEarlyWarning;
  item.json.alert_type = isEarlyWarning ? 'GRADE_DROP_WARNING' : 'STANDARD_REPORT';
}

return $input.all();

